from flask import Flask, request, redirect, render_template, session
import sqlite3

app = Flask(__name__)
app.secret_key = 'your_secret_key'

@app.route('/buy', methods=['GET', 'POST'])
def buy():
    if request.method == 'POST':
        username = session.get('username')
        stock_name = request.form['stock_name']
        stock_quantity = int(request.form['stock_quantity'])

        # データベース接続
        conn = sqlite3.connect('trading.db')
        cursor = conn.cursor()

        # 既に注文済みか確認
        cursor.execute('SELECT * FROM orders WHERE username = ? AND stock_name = ?', (username, stock_name))
        existing_order = cursor.fetchone()

        if existing_order:
            error_message = "この銘柄についてはすでに注文済みです。"
            return render_template('buy.html', error_message=error_message)

        # 注文をデータベースに挿入
        cursor.execute('INSERT INTO orders (username, stock_name, stock_quantity) VALUES (?, ?, ?)',
                       (username, stock_name, stock_quantity))
        conn.commit()
        conn.close()

        # プロフィールページにリダイレクト
        return redirect('/profile')

    return render_template('buy.html')

@app.route('/profile')
def profile():
    username = session.get('username')
    if not username:
        return redirect('/login')
    return render_template('profile.html', username=username)

if __name__ == '__main__':
    app.run(debug=True)
